      p.y += p.vy * dt; p.x += p.dx * dt + Math.sin(t * 0.7 * p.f + p.ph) * 0.0006;
      var a = Math.sin(Math.PI * p.life / p.max) * (0.55 + 0.45 * Math.sin(t * 2.2 * p.f + p.ph));
      if (a <= 0.01) continue;
